content:
{
  "tools": [
    {
      "name": "get_stock_quote",
      "description": "Retrieves the current real-time quote for a given stock ticker symbol, including price, volume, and last trade time.",
      "parameters": {
        "type": "object",
        "properties": {
          "ticker_symbol": {
            "type": "string",
            "description": "The ticker symbol of the stock (e.g., AAPL, GOOGL)."
          }
        },
        "required": [
          "ticker_symbol"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "symbol": {
            "type": "string"
          },
          "price": {
            "type": "number"
          },
          "volume": {
            "type": "integer"
          },
          "last_trade_time": {
            "type": "string",
            "format": "date-time"
          }
        }
      }
    },
    {
      "name": "search_stocks_by_industry",
      "description": "Searches for stocks belonging to a specified industry, optionally filtering by market capitalization range.",
      "parameters": {
        "type": "object",
        "properties": {
          "industry": {
            "type": "string",
            "description": "The industry to search for (e.g., 'Technology', 'Healthcare')."
          },
          "min_market_cap_usd": {
            "type": "number",
            "description": "Minimum market capitalization in USD to filter results (e.g., 1000000000)."
          },
          "max_market_cap_usd": {
            "type": "number",
            "description": "Maximum market capitalization in USD to filter results (e.g., 50000000000)."
          },
          "exchange": {
            "type": "string",
            "description": "The stock exchange to filter by (e.g., 'NYSE', 'NASDAQ')."
          }
        },
        "required": [
          "industry"
        ]
      },
      "response_schema": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "symbol": {
              "type": "string"
            },
            "company_name": {
              "type": "string"
            },
            "industry": {
              "type": "string"
            },
            "market_cap_usd": {
              "type": "number"
            }
          }
        }
      }
    },
    {
      "name": "get_historical_prices",
      "description": "Retrieves historical daily closing prices for a given stock ticker symbol over a specified date range.",
      "parameters": {
        "type": "object",
        "properties": {
          "ticker_symbol": {
            "type": "string",
            "description": "The ticker symbol of the stock (e.g., MSFT)."
          },
          "start_date": {
            "type": "string",
            "format": "date",
            "description": "The start date for the historical data in YYYY-MM-DD format."
          },
          "end_date": {
            "type": "string",
            "format": "date",
            "description": "The end date for the historical data in YYYY-MM-DD format."
          }
        },
        "required": [
          "ticker_symbol",
          "start_date",
          "end_date"
        ]
      },
      "response_schema": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "date": {
              "type": "string",
              "format": "date"
            },
            "close_price": {
              "type": "number"
            },
            "volume": {
              "type": "integer"
            }
          }
        }
      }
    },
    {
      "name": "place_trade_order",
      "description": "Places a buy or sell trade order for a specified stock, quantity, and order type.",
      "parameters": {
        "type": "object",
        "properties": {
          "ticker_symbol": {
            "type": "string",
            "description": "The ticker symbol of the stock to trade."
          },
          "order_type": {
            "type": "string",
            "enum": [
              "buy",
              "sell"
            ],
            "description": "The type of order: 'buy' or 'sell'."
          },
          "quantity": {
            "type": "integer",
            "description": "The number of shares to trade."
          },
          "limit_price": {
            "type": "number",
            "description": "Optional: The limit price for a limit order. If not provided, it's a market order."
          },
          "is_market_order": {
            "type": "boolean",
            "description": "Set to true for a market order, false for a limit order (requires limit_price)."
          }
        },
        "required": [
          "ticker_symbol",
          "order_type",
          "quantity",
          "is_market_order"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "order_id": {
            "type": "string"
          },
          "status": {
            "type": "string"
          },
          "message": {
            "type": "string"
          }
        }
      }
    },
    {
      "name": "get_portfolio_holdings",
      "description": "Retrieves the current stock holdings for a specific portfolio ID, including shares, average cost, and current value.",
      "parameters": {
        "type": "object",
        "properties": {
          "portfolio_id": {
            "type": "string",
            "description": "The unique identifier for the portfolio."
          }
        },
        "required": [
          "portfolio_id"
        ]
      },
      "response_schema": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "ticker_symbol": {
              "type": "string"
            },
            "shares_held": {
              "type": "integer"
            },
            "average_cost_per_share": {
              "type": "number"
            },
            "current_value_usd": {
              "type": "number"
            }
          }
        }
      }
    },
    {
      "name": "cancel_trade_order",
      "description": "Cancels a pending trade order using its unique order ID.",
      "parameters": {
        "type": "object",
        "properties": {
          "order_id": {
            "type": "string",
            "description": "The unique identifier of the trade order to cancel."
          },
          "portfolio_id": {
            "type": "string",
            "description": "The portfolio ID associated with the order."
          }
        },
        "required": [
          "order_id",
          "portfolio_id"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "order_id": {
            "type": "string"
          },
          "status": {
            "type": "string"
          },
          "message": {
            "type": "string"
          }
        }
      }
    }
  ]
}

{
  "tools": [
    {
      "name": "convert_length",
      "description": "Converts a length value from one unit to another (e.g., meters to feet, inches to centimeters).",
      "parameters": {
        "type": "object",
        "properties": {
          "value": {
            "type": "number",
            "description": "The numeric value to convert."
          },
          "from_unit": {
            "type": "string",
            "description": "The unit of the input value (e.g., 'meter', 'foot', 'inch', 'centimeter')."
          },
          "to_unit": {
            "type": "string",
            "description": "The desired unit for the output value (e.g., 'yard', 'kilometer', 'mile')."
          },
          "precision": {
            "type": "integer",
            "description": "The number of decimal places for the converted value. Defaults to 2."
          }
        },
        "required": [
          "value",
          "from_unit",
          "to_unit"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "converted_value": {
            "type": "number",
            "description": "The value after conversion."
          },
          "unit": {
            "type": "string",
            "description": "The unit of the converted value."
          },
          "original_value": {
            "type": "number",
            "description": "The original value provided."
          },
          "original_unit": {
            "type": "string",
            "description": "The original unit provided."
          }
        }
      }
    },
    {
      "name": "convert_temperature",
      "description": "Converts a temperature value between different scales (e.g., Celsius to Fahrenheit, Kelvin to Celsius).",
      "parameters": {
        "type": "object",
        "properties": {
          "value": {
            "type": "number",
            "description": "The numeric temperature value to convert."
          },
          "from_unit": {
            "type": "string",
            "description": "The unit of the input temperature (e.g., 'celsius', 'fahrenheit', 'kelvin')."
          },
          "to_unit": {
            "type": "string",
            "description": "The desired unit for the output temperature."
          }
        },
        "required": [
          "value",
          "from_unit",
          "to_unit"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "converted_temperature": {
            "type": "number",
            "description": "The temperature after conversion."
          },
          "unit": {
            "type": "string",
            "description": "The unit of the converted temperature."
          }
        }
      }
    },
    {
      "name": "get_supported_units",
      "description": "Retrieves a list of all supported units for a given conversion category (e.g., 'length', 'volume', 'mass'). This helps users understand what units can be used for conversions.",
      "parameters": {
        "type": "object",
        "properties": {
          "category": {
            "type": "string",
            "description": "The category of units to retrieve (e.g., 'length', 'volume', 'mass', 'temperature', 'area')."
          },
          "include_aliases": {
            "type": "boolean",
            "description": "If true, includes common aliases for units (e.g., 'm' for 'meter'). Defaults to false."
          }
        },
        "required": [
          "category"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "category": {
            "type": "string",
            "description": "The requested unit category."
          },
          "units": {
            "type": "string",
            "description": "A comma-separated string of supported units for the category."
          }
        }
      }
    },
    {
      "name": "convert_mass",
      "description": "Converts a mass value from one unit to another (e.g., kilograms to pounds, ounces to grams).",
      "parameters": {
        "type": "object",
        "properties": {
          "value": {
            "type": "number",
            "description": "The numeric value of mass to convert."
          },
          "from_unit": {
            "type": "string",
            "description": "The unit of the input mass (e.g., 'kilogram', 'pound', 'gram', 'ounce')."
          },
          "to_unit": {
            "type": "string",
            "description": "The desired unit for the output mass."
          },
          "round_to_nearest_half": {
            "type": "boolean",
            "description": "If true, rounds the converted value to the nearest half unit. Defaults to false."
          }
        },
        "required": [
          "value",
          "from_unit",
          "to_unit"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "converted_mass": {
            "type": "number",
            "description": "The mass after conversion."
          },
          "unit": {
            "type": "string",
            "description": "The unit of the converted mass."
          }
        }
      }
    },
    {
      "name": "convert_volume",
      "description": "Converts a volume value from one unit to another (e.g., liters to gallons, milliliters to fluid ounces).",
      "parameters": {
        "type": "object",
        "properties": {
          "value": {
            "type": "number",
            "description": "The numeric value of volume to convert."
          },
          "from_unit": {
            "type": "string",
            "description": "The unit of the input volume (e.g., 'liter', 'gallon', 'milliliter', 'fluid_ounce')."
          },
          "to_unit": {
            "type": "string",
            "description": "The desired unit for the output volume."
          },
          "decimal_places": {
            "type": "integer",
            "description": "The number of decimal places to round the result to. Maximum of 5. Defaults to 2."
          }
        },
        "required": [
          "value",
          "from_unit",
          "to_unit"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "converted_volume": {
            "type": "number",
            "description": "The volume after conversion."
          },
          "unit": {
            "type": "string",
            "description": "The unit of the converted volume."
          }
        }
      }
    },
    {
      "name": "check_conversion_status",
      "description": "Checks the status of the unit conversion service. This can be used to ensure the service is operational before attempting complex conversions.",
      "parameters": {
        "type": "object",
        "properties": {
          "service_name": {
            "type": "string",
            "description": "The name of the specific conversion service component to check (e.g., 'length_converter', 'temperature_converter'). Optional, checks all if not provided."
          },
          "verbose": {
            "type": "boolean",
            "description": "If true, provides more detailed status information. Defaults to false."
          }
        },
        "required": []
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "overall_status": {
            "type": "string",
            "description": "The overall status of the conversion service (e.g., 'operational', 'degraded', 'offline')."
          },
          "timestamp": {
            "type": "string",
            "description": "The time the status was checked."
          },
          "details": {
            "type": "string",
            "description": "Detailed status information, if verbose is true."
          }
        }
      }
    }
  ]
}

{
  "tools": [
    {
      "name": "search_encyclopedia_articles",
      "description": "Searches for articles within the encyclopedia based on keywords, categories, or publication date. This tool is useful for finding relevant information on a given topic.",
      "parameters": {
        "type": "object",
        "properties": {
          "keywords": {
            "type": "string",
            "description": "One or more keywords to search for within article titles or content."
          },
          "category": {
            "type": "string",
            "description": "Optional category to filter the search results (e.g., 'History', 'Science', 'Biography')."
          },
          "min_publication_year": {
            "type": "integer",
            "description": "Optional minimum publication year to filter articles."
          },
          "max_publication_year": {
            "type": "integer",
            "description": "Optional maximum publication year to filter articles."
          },
          "limit": {
            "type": "integer",
            "description": "The maximum number of articles to return in the search results (default: 10)."
          }
        },
        "required": [
          "keywords"
        ]
      },
      "response_schema": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "article_id": {
              "type": "string"
            },
            "title": {
              "type": "string"
            },
            "summary": {
              "type": "string"
            },
            "category": {
              "type": "string"
            },
            "publication_year": {
              "type": "integer"
            }
          }
        }
      }
    },
    {
      "name": "get_article_details",
      "description": "Retrieves the full content and metadata for a specific encyclopedia article using its unique ID. This allows for in-depth viewing of an article.",
      "parameters": {
        "type": "object",
        "properties": {
          "article_id": {
            "type": "string",
            "description": "The unique identifier of the encyclopedia article to retrieve."
          },
          "include_references": {
            "type": "boolean",
            "description": "Whether to include a list of references at the end of the article content (default: false)."
          }
        },
        "required": [
          "article_id"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "article_id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "category": {
            "type": "string"
          },
          "publication_year": {
            "type": "integer"
          },
          "author": {
            "type": "string"
          },
          "content": {
            "type": "string"
          },
          "last_updated": {
            "type": "string"
          },
          "references": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        }
      }
    },
    {
      "name": "submit_new_article_draft",
      "description": "Submits a new article draft for review by encyclopedia editors. This tool is used by contributors to add new information to the encyclopedia.",
      "parameters": {
        "type": "object",
        "properties": {
          "title": {
            "type": "string",
            "description": "The proposed title for the new article."
          },
          "category": {
            "type": "string",
            "description": "The primary category for the new article (e.g., 'History', 'Science')."
          },
          "content": {
            "type": "string",
            "description": "The full content of the article draft."
          },
          "author_name": {
            "type": "string",
            "description": "The name of the author submitting the draft."
          },
          "is_major_contribution": {
            "type": "boolean",
            "description": "Indicates if this is a substantial new article or a minor addition (default: true)."
          }
        },
        "required": [
          "title",
          "category",
          "content",
          "author_name"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "draft_id": {
            "type": "string",
            "description": "The unique ID assigned to the submitted draft."
          },
          "status": {
            "type": "string",
            "description": "The current status of the draft (e.g., 'pending_review')."
          },
          "message": {
            "type": "string",
            "description": "A confirmation message."
          }
        }
      }
    },
    {
      "name": "update_article_content",
      "description": "Updates the content of an existing encyclopedia article. This tool is for making corrections or additions to published articles.",
      "parameters": {
        "type": "object",
        "properties": {
          "article_id": {
            "type": "string",
            "description": "The unique identifier of the article to be updated."
          },
          "new_content": {
            "type": "string",
            "description": "The complete new content for the article. This will replace the existing content."
          },
          "editor_id": {
            "type": "string",
            "description": "The ID of the editor performing the update."
          },
          "minor_edit": {
            "type": "boolean",
            "description": "Set to true if this is a minor correction and does not require a full review process (default: false)."
          }
        },
        "required": [
          "article_id",
          "new_content",
          "editor_id"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "article_id": {
            "type": "string"
          },
          "status": {
            "type": "string"
          },
          "message": {
            "type": "string"
          },
          "last_updated": {
            "type": "string"
          }
        }
      }
    },
    {
      "name": "get_article_revision_history",
      "description": "Retrieves the revision history for a given encyclopedia article, showing who made changes and when. This is useful for tracking article evolution and accountability.",
      "parameters": {
        "type": "object",
        "properties": {
          "article_id": {
            "type": "string",
            "description": "The unique identifier of the encyclopedia article."
          },
          "limit": {
            "type": "integer",
            "description": "The maximum number of revisions to retrieve (default: 5)."
          }
        },
        "required": [
          "article_id"
        ]
      },
      "response_schema": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "revision_id": {
              "type": "string"
            },
            "timestamp": {
              "type": "string"
            },
            "editor_name": {
              "type": "string"
            },
            "summary_of_changes": {
              "type": "string"
            }
          }
        }
      }
    },
    {
      "name": "delete_article",
      "description": "Deletes an existing encyclopedia article from the system. This action requires administrative privileges and is irreversible.",
      "parameters": {
        "type": "object",
        "properties": {
          "article_id": {
            "type": "string",
            "description": "The unique identifier of the article to be deleted."
          },
          "admin_user_id": {
            "type": "string",
            "description": "The ID of the administrator performing the deletion."
          },
          "reason": {
            "type": "string",
            "description": "A brief explanation for the deletion."
          },
          "confirm_deletion": {
            "type": "boolean",
            "description": "Must be true to confirm the deletion action."
          }
        },
        "required": [
          "article_id",
          "admin_user_id",
          "reason",
          "confirm_deletion"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "article_id": {
            "type": "string"
          },
          "status": {
            "type": "string"
          },
          "message": {
            "type": "string"
          }
        }
      }
    }
  ]
}

