{
  "tools": [
    {
      "name": "lookup_definition",
      "description": "Retrieves the definition(s) of a given word. Can specify language and part of speech to narrow down results.",
      "parameters": {
        "type": "object",
        "properties": {
          "word": {
            "type": "string",
            "description": "The word to look up."
          },
          "language": {
            "type": "string",
            "description": "The language of the word (e.g., 'en' for English, 'es' for Spanish). Defaults to 'en'.",
            "enum": [
              "en",
              "es",
              "fr",
              "de"
            ]
          },
          "part_of_speech": {
            "type": "string",
            "description": "Filter definitions by part of speech (e.g., 'noun', 'verb', 'adjective').",
            "enum": [
              "noun",
              "verb",
              "adjective",
              "adverb",
              "pronoun",
              "preposition",
              "conjunction",
              "interjection"
            ]
          }
        },
        "required": [
          "word"
        ]
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "word": {
            "type": "string"
          },
          "language": {
            "type": "string"
          },
          "definitions": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "part_of_speech": {
                  "type": "string"
                },
                "text": {
                  "type": "string"
                },
                "example": {
                  "type": "string"
                }
              }
            }
          },
          "pronunciations": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        }
      }
    },
    {
      "name": "get_word_of_the_day",
      "description": "Retrieves the 'word of the day' for a specified date and language. This can be used to discover new vocabulary.",
      "parameters": {
        "type": "object",
        "properties": {
          "date": {
            "type": "string",
            "description": "The date for which to retrieve the word of the day, in YYYY-MM-DD format. Defaults to today's date if not provided."
          },
          "language": {
            "type": "string",
            "description": "The language for the word of the day (e.g., 'en' for English). Defaults to 'en'.",
            "enum": [
              "en",
              "es",
              "fr"
            ]
          }
        },
        "required": []
      },
      "response_schema": {
        "type": "object",
        "properties": {
          "date": {
            "type": "string"
          },
          "word": {
            "type": "string"
          },
          "definition": {
            "type": "string"
          },
          "example_sentence": {
            "type": "string"
          },
          "pronunciation": {
            "type": "string"
          }
        }
      }
    },
